using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ShipmentServerService(ApplicationDbContext db, UserManager<ApplicationUser> userManager) : IShipmentService
{
    public async Task<List<ShipmentDto>> GetAllShipmentsAsync()
    {
        return await db.Shipments
            .Include(s => s.Customer)
            .OrderByDescending(s => s.LastUpdated)
            .Select(s => MapToDto(s))
            .ToListAsync();
    }

    public async Task<ShipmentDto?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var shipment = await db.Shipments
            .Include(s => s.Customer)
            .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
        return shipment is null ? null : MapToDto(shipment);
    }

    public async Task<List<ShipmentDto>> GetShipmentsForCustomerAsync()
    {
        // This method is only called from API endpoints where user is identified via HttpContext
        // When called server-side, it won't have context - use GetShipmentsForCustomerByIdAsync instead
        return await db.Shipments
            .Include(s => s.Customer)
            .OrderByDescending(s => s.LastUpdated)
            .Select(s => MapToDto(s))
            .ToListAsync();
    }

    public async Task<List<ShipmentDto>> GetShipmentsForCustomerByIdAsync(string userId)
    {
        return await db.Shipments
            .Include(s => s.Customer)
            .Where(s => s.CustomerId == userId)
            .OrderByDescending(s => s.LastUpdated)
            .Select(s => MapToDto(s))
            .ToListAsync();
    }

    public async Task<ShipmentDto> CreateShipmentAsync(CreateShipmentRequest request)
    {
        var customer = await userManager.FindByEmailAsync(request.CustomerEmail);
        var shipment = new Shipment
        {
            TrackingNumber = GenerateTrackingNumber(),
            Origin = request.Origin,
            Destination = request.Destination,
            Status = ShipmentStatus.Pending,
            EstimatedDelivery = request.EstimatedDelivery,
            CustomerId = customer?.Id ?? string.Empty,
            CreatedAt = DateTimeOffset.UtcNow,
            LastUpdated = DateTimeOffset.UtcNow
        };

        db.Shipments.Add(shipment);
        await db.SaveChangesAsync();

        // Reload with customer
        await db.Entry(shipment).Reference(s => s.Customer).LoadAsync();
        return MapToDto(shipment);
    }

    public async Task UpdateShipmentStatusAsync(int id, UpdateShipmentStatusRequest request)
    {
        var shipment = await db.Shipments.FindAsync(id)
            ?? throw new InvalidOperationException("Shipment not found");

        shipment.Status = request.Status;
        shipment.ActualDelivery = request.ActualDelivery;
        shipment.LastUpdated = DateTimeOffset.UtcNow;

        await db.SaveChangesAsync();
    }

    private static ShipmentDto MapToDto(Shipment s) => new()
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = s.Status,
        EstimatedDelivery = s.EstimatedDelivery,
        ActualDelivery = s.ActualDelivery,
        CustomerEmail = s.Customer?.Email ?? string.Empty,
        CreatedAt = s.CreatedAt,
        LastUpdated = s.LastUpdated
    };

    private static string GenerateTrackingNumber()
    {
        return $"ST-{DateTime.UtcNow:yyyyMMdd}-{Guid.NewGuid().ToString()[..8].ToUpperInvariant()}";
    }
}

