@page "/dispatcher"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize(Roles = "Dispatcher")]
@inject IShipmentService ShipmentService

<PageTitle>Dispatcher Dashboard</PageTitle>

<h1>Dispatcher Dashboard</h1>

<div class="mb-3 d-flex gap-2">
    <input type="text" class="form-control" placeholder="Filter by destination..." @bind="destinationFilter" @bind:event="oninput" />
    <select class="form-select" @bind="statusFilter" style="max-width: 200px;">
        <option value="">All Statuses</option>
        @foreach (var status in Enum.GetValues<ShipmentStatus>())
        {
            <option value="@status">@status</option>
        }
    </select>
    <button class="btn btn-primary" @onclick="ToggleCreateForm">Create Shipment</button>
</div>

@if (showCreateForm)
{
    <div class="card mb-3 p-3">
        <h5>Create New Shipment</h5>
        <div class="row g-2">
            <div class="col-md-3">
                <input type="text" class="form-control" placeholder="Origin" @bind="newShipment.Origin" />
            </div>
            <div class="col-md-3">
                <input type="text" class="form-control" placeholder="Destination" @bind="newShipment.Destination" />
            </div>
            <div class="col-md-3">
                <input type="email" class="form-control" placeholder="Customer Email" @bind="newShipment.CustomerEmail" />
            </div>
            <div class="col-md-3">
                <input type="datetime-local" class="form-control" @bind="estimatedDeliveryInput" />
            </div>
        </div>
        <div class="mt-2">
            <button class="btn btn-success" @onclick="CreateShipment">Submit</button>
            <button class="btn btn-secondary ms-2" @onclick="ToggleCreateForm">Cancel</button>
        </div>
    </div>
}

@if (shipments is null)
{
    <p>Loading...</p>
}
else
{
    <table class="table table-striped">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Origin</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Estimated Delivery</th>
                <th>Last Updated</th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var shipment in FilteredShipments)
            {
                <tr>
                    <td>@shipment.TrackingNumber</td>
                    <td>@shipment.Origin</td>
