    private string destinationFilter = string.Empty;
    private string statusFilter = string.Empty;
    private int? updatingId;
    private ShipmentStatus newStatus;

    private IEnumerable<ShipmentDto> FilteredShipments => shipments?.Where(s =>
        (string.IsNullOrEmpty(destinationFilter) || s.Destination.Contains(destinationFilter, StringComparison.OrdinalIgnoreCase)) &&
        (string.IsNullOrEmpty(statusFilter) || s.Status.ToString() == statusFilter)
    ) ?? [];

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private void ToggleCreateForm() => showCreateForm = !showCreateForm;

    private async Task CreateShipment()
    {
        if (estimatedDeliveryInput.HasValue)
            newShipment.EstimatedDelivery = new DateTimeOffset(estimatedDeliveryInput.Value);

        await ShipmentService.CreateShipmentAsync(newShipment);
        newShipment = new();
        estimatedDeliveryInput = null;
        showCreateForm = false;
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private void StartStatusUpdate(ShipmentDto shipment)
    {
        updatingId = shipment.Id;
        newStatus = shipment.Status;
    }

    private async Task SubmitStatusUpdate(int id)
    {
        var request = new UpdateShipmentStatusRequest
        {
            Status = newStatus,
            ActualDelivery = newStatus == ShipmentStatus.Delivered ? DateTimeOffset.UtcNow : null
        };
        await ShipmentService.UpdateShipmentStatusAsync(id, request);
        updatingId = null;
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

