@using ShipmentTracker.Client.Models

<div class="card h-100">
    <div class="card-body">
        <h6 class="card-title">@Shipment.TrackingNumber</h6>
        <p class="card-text mb-1"><strong>@Shipment.Origin</strong> → <strong>@Shipment.Destination</strong></p>
        <div class="mb-2">
            <span class="badge @GetStatusBadgeClass(Shipment.Status)">@Shipment.Status</span>
        </div>
        <div class="progress mb-2" style="height: 8px;">
            <div class="progress-bar @GetProgressBarClass(Shipment.Status)" role="progressbar"
                 style="width: @GetProgressPercent(Shipment.Status)%"></div>
        </div>
        <small class="text-muted d-block">
            @if (Shipment.EstimatedDelivery.HasValue)
            {
                <span>Est. Delivery: @Shipment.EstimatedDelivery.Value.LocalDateTime.ToString("MMM dd, yyyy")</span>
            }
        </small>
        @if (Shipment.ActualDelivery.HasValue)
        {
            <small class="text-success d-block">
                Delivered: @Shipment.ActualDelivery.Value.LocalDateTime.ToString("MMM dd, yyyy h:mm tt")
            </small>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public ShipmentDto Shipment { get; set; } = null!;

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.InTransit => "bg-info",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };

    private static string GetProgressBarClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.InTransit => "bg-info",
        ShipmentStatus.OutForDelivery => "bg-warning",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };

    private static int GetProgressPercent(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => 10,
        ShipmentStatus.InTransit => 40,
        ShipmentStatus.OutForDelivery => 75,
        ShipmentStatus.Delivered => 100,
        ShipmentStatus.Cancelled => 100,
        _ => 0
    };
}

@using ShipmentTracker.Client.Models

<div class="card h-100">
    <div class="card-body">
        <h6 class="card-title">@Shipment.TrackingNumber</h6>
        <p class="card-text mb-1"><strong>@Shipment.Origin</strong> → <strong>@Shipment.Destination</strong></p>
        <div class="mb-2">
            <span class="badge @GetStatusBadgeClass(Shipment.Status)">@Shipment.Status</span>
        </div>
        <div class="progress mb-2" style="height: 8px;">
            <div class="progress-bar @GetProgressBarClass(Shipment.Status)" role="progressbar"
                 style="width: @GetProgressPercent(Shipment.Status)%"></div>
        </div>
        <small class="text-muted d-block">
            @if (Shipment.EstimatedDelivery.HasValue)
            {
                <span>Est. Delivery: @Shipment.EstimatedDelivery.Value.LocalDateTime.ToString("MMM dd, yyyy")</span>
            }
        </small>
        @if (Shipment.ActualDelivery.HasValue)
        {
            <small class="text-success d-block">
                Delivered: @Shipment.ActualDelivery.Value.LocalDateTime.ToString("MMM dd, yyyy h:mm tt")
            </small>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public ShipmentDto Shipment { get; set; } = null!;

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.InTransit => "bg-info",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };

    private static string GetProgressBarClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.InTransit => "bg-info",
        ShipmentStatus.OutForDelivery => "bg-warning",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };

    private static int GetProgressPercent(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => 10,
        ShipmentStatus.InTransit => 40,
        ShipmentStatus.OutForDelivery => 75,
        ShipmentStatus.Delivered => 100,
        ShipmentStatus.Cancelled => 100,
        _ => 0
    };
}

